function v26_additions_total(int $uid,string $month):float {$total=0.0;foreach(query("SELECT amount,body_json FROM ep_records WHERE user_id=? AND module='addition' AND status='approved'",[$uid])->fetchAll()as $r)if((decode($r['body_json'])['month']??'')===$month)$total+=(float)$r['amount'];return round($total,3);}
function v26_payroll_version(array $p,array $u,string $event,string $note=''):void {v26_insert('payroll_version',(int)$p['user_id'],$p['month_key'].'-01',null,['payroll_id'=>(int)$p['id'],'event'=>$event,'actor'=>(int)$u['id'],'at'=>utc_now(),'note'=>$note,'before'=>$p]);audit('payroll_'.$event,'payroll:'.$p['id'],['status'=>$p['status'],'note'=>$note,'actor'=>$u['id']]);}
function v26_payroll_snapshot_month(string $month,array $u,?string $company41=null):void {foreach(query("SELECT * FROM ep_payroll WHERE month_key=? AND status IN ('draft','returned')",[$month])->fetchAll()as $p){$GLOBALS['EP_SCREEN']='payroll';if(in_array((int)$p['user_id'],permission_scope29($u,'payroll','create'),true)&&pay41_build_matches(employee_required((int)$p['user_id']),$month,$company41))v26_payroll_version($p,$u,'rebuild');}}
function v26_permit_at(int $uid,string $date):?array {$r=query("SELECT TOP (1) * FROM ep_records WHERE user_id=? AND module='work_permit' AND status='approved' AND date_from<=? AND date_to>=? ORDER BY date_from DESC,id DESC",[$uid,$date,$date])->fetch();if($r){$v=decode($r['body_json']);return array_key_exists('confirmed_active',$v)&&!$v['confirmed_active']?null:$r;}foreach(query("SELECT * FROM ep_records WHERE user_id=? AND module='work_permit' AND status='approved' ORDER BY id DESC",[$uid])->fetchAll()as $candidate){$v=decode($candidate['body_json']);if(!empty($v['incomplete_dates'])&&!empty($v['confirmed_active'])&&($v['confirmed_on']??$candidate['date_from'])<=$date)return $candidate;}return null;}
function v26_leave_paid_amounts(int $uid):array {
 $out=[];foreach(query("SELECT * FROM ep_records WHERE user_id=? AND module='payment' AND status='approved' ORDER BY date_from,id",[$uid])->fetchAll()as $p){$b=decode($p['body_json']);$alloc=$b['leave_allocations']??[];if(!$alloc&&($b['kind']??'')==='leave_cash')$alloc=[['id'=>(int)$b['source_id'],'amount'=>(float)$p['amount']]];foreach($alloc as $a)$out[(int)$a['id']]=round(($out[(int)$a['id']]??0)+(float)$a['amount'],3);}return $out;
